(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fo"] = {"ui":{"skip":"Far til innihaldið","back":"← Aftur til AI-gile","lang.button":"Mál: {name}","lang.dialog":"Vel eitt mál","lang.search":"Leita eftir máli","lang.none":"Einki mál hóvar","lang.notYet":"{name} er ikki umsett enn","theme.aria":"Skift millum ljósan og myrkan hátt","theme.toLight":"Skift til ljósan hátt","theme.toDark":"Skift til myrkan hátt","index.title":"AI-gile: títt AI-menningarlið, á einum borði","index.description":"AI-gile er eitt kanban-borð til AI-kodulið. Tey arbeiða meðan tú sovir; tú fært ein stuttan bunka við tilfarið at taka avgerð um, royna og góðkenna.","hero.logoAlt":"AI-gile borðtekn","hero.h1.html":"Títt AI-menningarlið, á einum&nbsp;borði.","hero.alpha":"🐣 Lukkað pre-alfa","hero.alphaTitle":"Tíðliga og ikki liðugt: takk fyri at royna!","hero.lede":"Tey byggja meðan tú sovir. Tú vaknar til ein stuttan bunka: nøkur spurningar, nøkur at royna, ein ella tveir purpurdiamantir. Klikk, góðkent, aftur til kaffibollan.","dl.windows":"Windows-app","dl.browser":"Brúka í kagarinum","dl.soon":"Kemur skjótt","dl.notify":"🔔 Boða mær frá, tá tað letur upp","dl.notifySmall":"Alfa ella beta","hero.secondary":"Agile, men liðið hevur ongantíð brúk fyri standandi-fundar-kaffi. (Tey hava standandi fund kortini.)","pitch.h2":"AI-gile í so nógvum orðum, sum tú vilt","pitch.lede":"Vel eina longd, frá einum orði upp í 144. Hvør longd er sín egni frágreiðing, skrivað til tann stødd. Drag rennuna ella brúka pílarnar.","pitch.rangeLabel":"Longd í orðum","pitch.dice":"🎲 ein onnur útgáva","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} bókstavur","pitch.letters.other":"{n} bókstavir","pitch.chars.one":"{n} tekin","pitch.chars.other":"{n} tekin","count.line.html.one":"{n} kort á borðinum júst nú","count.line.html.other":"{n} kort á borðinum júst nú","features.aria":"Hvat tað ger","f.pile.h":"Ein bunki til tín","f.pile.html":"<b>Fyri teg</b> inniheldur alt, sum bíðar eftir tær, í øllum verkætlanum: spurningar, tilfar at royna, uppgávur, sum bara ein maður kann gera. Tín bíðirøð sigur, hvat er næst og hvussu leingi tað tekur.","f.sleep.h":"Lið, sum arbeiða meðan tú sovir","f.sleep.p":"Hvør verkætlan hevur ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á eitt kort, og liðið vaknar, ger arbeiðið og gevur tær tað aftur við stigum, sum eisini ein móður maður kann fylgja.","f.tester.h":"Ein AI-royndari kannar fyrst","f.tester.p":"Áðrenn nakað kemur til tín, fylgir ein royndari stigunum í einum avriti av appini og vísir, hvat hann sá, við skíggjamynd. Blaða tú gjøgnum tey, sum eru greidd, og góðkenn við einum klikki.","f.proof.h":"Prógv, ikki lyfti","f.proof.p":"Hvør yvirlatan vísir, hvat broytt er: fílurnar, diff-ið, skíggjamyndirnar. Tú sleppur undan at lata hvørt app upp fyri at sæa, um tað er liðugt.","f.chat.h":"Práta við leiðararnar hjá tær","f.chat.p":"Ein Discord-líknandi rekki: eitt tekn fyri hvørja verkætlan, purpurdiamantir fyri tað, sum hevur brúk fyri tær. Send leiðaranum eitt hugskot; hann ger kort og eina ætlan burturúr, við einum ✅ Go-knappi.","f.tidy.h":"Heldur seg sjálvt rættiliga","f.tidy.p":"Kort, sum hanga saman, renna saman, ruglaðir heitir verða rættaðir, og ein tokenkanning heldur kodu lættari. Færri ting at skifta millum, minni at hugsa um.","f.private.h":"Títt, á tíni teldu","f.private.li1":"Borðið koyrir á tínari egnu maskinu og svarar bara tær.","f.private.li2":"Privatar boð millum fólk eru enda-til-enda krypterað.","f.private.li3":"Eingin konta, ongir fylgjarar, ongar cookies.","f.lang.h":"Á tínum máli","f.lang.p":"Meiri enn 120 mál, frá hollendskum, valisiskum og japanskum til sjóræningamál, Yoda og klingonskt, við skjótum skifti aftur til enskt fyri orðini hjá menningarfólki.","tl.aria":"Tíðarlinja frá fyrsta samrøðu til vegakortið","tl.h2":"Frá fyrstu práti til tað, sum er næst","tl.lede":"Veruligar dagar og tíðir, í tínum egna tíðarsvæði. Aftaná í dag er tað ætlanin, uttan lovaðar dagar.","tl.today":"Í dag","tl.planned":"ætlað","tl.cards.one":"{n} kort","tl.cards.other":"{n} kort","join.h2":"Vertu við","join.lede":"AI-gile verður bygt av einum lítlum manni og nógvum tolnum agentum. Tað er privat enn, í lukkaðari alfu saman við vinum. Vilt tú royna, tá tað letur upp?","join.btn":"Boða frá áhuga","join.small":"Vit senda tær teldupost, einki annað","footer.tag":"AI-gile. Ongir fylgjarar, ongar cookies, einki standandi-fundar-kaffi.","footer.licence":"Fyritøkuloyvi","footer.status":"Støða","form.sending":"Sendi…","form.failed":"Tað riggaði ikki: royn aftur seinni.","form.offline":"Fekk ikki samband við AI-gile: royn aftur seinni.","interest.title":"AI-gile: boða mær frá, tá alfan letur upp","interest.description":"Skriva tín teldupost fyri at frætta, tá lukkaða alfan ella betan hjá AI-gile letur upp.","interest.h1":"🔔 Boða mær frá, tá tað letur upp","interest.lede":"AI-gile er í lukkaðari pre-alfu. Skriva tín teldupost, og vit skriva tær eina ferð, tá pláss er til tín.","interest.email":"Tín teldupostur","interest.which":"Hvør royndin?","interest.alpha":"Lukkað alfa: tíðliga, ruggað, nógvar broytingar","interest.beta":"Beta: støðugari, seinni","interest.both":"Annaðhvørt, hvat so fyrst letur upp","interest.submit":"Set meg á listan","interest.thanks":"Takk! Tú ert á listanum.","interest.kept":"Bara tín teldupostur og royndin, tú vald, verða goymd, bara til henda listan. Einki fregnbræv, ongir fylgjarar.","licence.title":"AI-gile: fyritøkuloyvi","licence.description":"Brúkar tú AI-gile í tíni fyritøku? Søk um eitt ókeypis fyritøkuloyvi.","licence.h1":"📜 Fyritøkuloyvi","licence.lede":"Brúkar tú AI-gile á arbeiðsplássinum? Sig okkum, hvør tú ert og hvat tú gert. Um tað ger gott, er loyvið ókeypis.","licence.company":"Fyritøka","licence.website":"Heimasíða","licence.what":"Hvat tú gert","licence.how":"Hvussu tað hjálpir heiminum","licence.email":"Teldupostur","licence.submit":"Søk","licence.thanks":"Takk! Vit svara við teldupósti.","status.title":"AI-gile støða","status.h1":"AI-gile støða","status.quiet":"Alt er kvirt","status.checking":"Kanni…","status.offline":"Fái ikki samband við støðutænastuna júst nú (royni aftur)","status.updated":"dagført {ago}","status.justNow":"júst nú","status.min":"{n} min síðani","status.hours":"{n} t síðani","status.days":"{n} d síðani","live.h2":"Sær tað verða bygt, beinleiðis","live.caption":"Hvert kort er fjalt: tú sært skapið á arbeiðinum, ikki orðini.","live.watching.one":"beinleiðis: {n} hyggja","live.watching.other":"beinleiðis: {n} hyggja","live.offline":"Beinleiðis talvan tekur sær eina løtu at kvíla. Kom aftur skjótt.","live.cols":"Backlog|At gera|Í gerð|Toymið kannar|Fyri teg at testa|Fyri toymið|Liðugt","live.last.now":"Seinasta kort flutt júst nú","live.last.min.one":"Seinasta kort flutt fyri {n} min síðani","live.last.min.other":"Seinasta kort flutt fyri {n} min síðani","live.last.hour.one":"Seinasta kort flutt fyri {n} tíma síðani","live.last.hour.other":"Seinasta kort flutt fyri {n} tímum síðani","live.last.day.one":"Seinasta kort flutt fyri {n} degi síðani","live.last.day.other":"Seinasta kort flutt fyri {n} døgum síðani"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotar.","Avgreitt."]},{"n":2,"texts":["Robotar arbeiða.","Agentar, skipaðir.","Hugskot, bygd."]},{"n":3,"texts":["Kanban fyri robotar.","Hugskot verða eyðkenni.","Ókeypis agent-kanban."]},{"n":5,"texts":["Kanban-borð rikið av agentum.","Tú skrivar, agentar byggja.","Ókeypis, lokalt, roynt, eitt sindur tilkomið."]},{"n":8,"texts":["Eitt ókeypis kanban-borð, har AI-agentar arbeiða.","Skriva eitt hugskot. Agentar byggja. Tú góðkennir.","Agile fyri ein mann og nógvar tolnar robotar."]},{"n":13,"texts":["Eitt kanban-borð á tíni teldu, har AI-agentar taka kortini og gera arbeiðið.","Skriva eitt hugskot. Eitt lið av agentum bygger tað. Ein royndari kannar tað.","Ókeypis, eingin konta, ongir fylgjarar: eitt borð, nakrir robotar, og tú ræður."]},{"n":21,"texts":["AI-gile er eitt kanban-borð at arbeiða saman við AI-kodaagentum. Tey taka kortini; tú roynir tey og góðkennir tey.","Hvør verkætlan fær ein leiðara og eitt lið av AI-agentum. Skriva eina viðmerking á hvørt kort, og liðið fer til verka.","Eitt ókeypis, persónligt uppgávuborð, sum koyrir á tíni egnu teldu. Arbeiðararnir eru robotar. Tann, sum sigur ja, ert tú."]},{"n":34,"texts":["Tú leggur hugskot á eitt borð. Eitt lið av AI-agentum ger tey til virkandi eyðkenni, roynir tey og gevur tær tey aftur við stigum at royna. Einki telst sum liðugt, fyrr enn tú sigur tað.","AI-gile er eitt heimagjørt kanban-borð, sum Rich bygdi við nógvari hjálp frá teimum agentum, sum tað nú stýrir. Tað er ókeypis, koyrir á tíni teldu og verður deilt við vinir, ikki selt.","Hugsa tær eitt vanligt kanban-borð, við súlum frá Backlog til Liðugt, nema at kortini verða tikin av AI-agentum. Tey boða frá framgongd, spyrja, tá tey sita fast, og bíða altíð eftir tínari góðkenning."]},{"n":55,"texts":["AI-gile er eitt kanban-borð, har liðið er gjørt av AI-agentum. Hvør verkætlan hevur ein leiðara, sum ætlar arbeiðið, og hjálparar, sum byggja tað. Tá eitt eyðkenni er klárt, roynir ein AI-royndari tað og tekur eina skíggjamynd, síðani kemur tað í tín bunka. Góðkenn tað, ella skriva eina viðmerking, og tey gera tað umaftur.","Tað byrjaði sum háttur hjá einum manni at fylgja við í nógvum AI-kodusessiónum í senn, og vaks til eitt veruligt borð. Tað koyrir á tíni maskinu, krevur onga kontu og hevur ongar fylgjarar. Tað er ókeypis fyri vinir og forvitin. Tað er eisini ikki liðugt, so ríkna við rúgvum kantum og einstaka undran.","Her er sanna útgávan. Tú mást enn hava hugskotini, og tú mást enn kanna úrslitini. Tað, sum AI-gile ger, er alt hitt ímillum: tað heldur kortunum í røð, vekur røttan agent, tá tú skrivar viðmerking, vísir júst hvat broytt er, og leggur alt í ein stuttan bunka til tín."]},{"n":89,"texts":["AI-gile er eitt ókeypis kanban-borð, sum tú letur koyra á tíni egnu teldu. Í staðin fyri fólk hevur hvør verkætlan eitt lið av AI-agentum: ein leiðara, sum ger hugskotini hjá tær til kort og eina ætlan, og hjálparar, sum taka kortini í raðfylgju eftir týdningi. Tá okkurt er bygt, fylgir ein AI-royndari royndarstigunum og vísir tær, hvat hann sá. Síðani bíðar tað í einum bunka, sum eitur Fyri teg. Tú góðkennir tað, ella tú skrivar eina viðmerking, og liðið roynir enn eina ferð. Einki kemur nakrantíð til Liðugt uttan teg.","Nøkur eyðkenni, sum tú kanska ikki væntar. Ein náttarvakt heldur súlini At gera fullari, meðan tú sovir, og velur kort, sum ikki hava brúk fyri svari frá tær. Ein tokentalari vísir, hvussu nógv agentarnir hava brúkt í dag og hesa vikuna, og Eingin token-hátturin sigur teimum at steðga at brúka. Tú kanst senda vinum boð, og privat boð eru enda-til-enda krypterað. Borðið tosar umleið 120 mál, millum annað hollendskt, flamskt, sjóræningamál og klingonskt. Einki av hesum kostar ein oyra, og ongin roynir at selja tær tað.","AI-gile er eitt lítið, persónligt tiltak, ikki ein fyritøka. Rich vildi taka sær av fleiri AI-kodaverkætlanum uttan at lata hvørt app upp fyri at kanna tær, so hann og agentarnir bygdu eitt borð til tað, og brúktu síðani borðið til at byggja restina av sær sjálvum. Tað er í lukkaðari pre-alfu, sum merkir, at tað riggar, mestsum, fyri ein bólk av vinum. Her er eingin prísasíða, einki fregnbræv og ongin vøkstrarætlan. Um tað ljóðar nyttigt, kanst tú biðja um at royna tað, tá tað letur eitt sindur meiri upp."]},{"n":144,"texts":["AI-gile er eitt kanban-borð fyri ein mann og nógvar AI-agentar. Tað koyrir á tíni egnu teldu og er heilt ókeypis. Tú leggur verkætlanir afturat, og hvør verkætlan fær ein leiðara og eitt lítið lið. Tú prátar við leiðaran, eitt sindur sum á Discord, og lýsir eitt hugskot; leiðarin ger kort og eina ætlan burturúr og bíðar síðani eftir, at tú trýstir á Go. Liðið arbeiðir seg gjøgnum kortini í raðfylgju eftir týdningi, við einari einfaldari boðraðlinju gjørdari til málmodellir. Áðrenn nakað kemur aftur til tín, fylgir ein AI-royndari stigunum í einum avriti av appini og leggur eina skíggjamynd við. Liðugt arbeiði kemur í tín bunka við broyttum fílum og diff-inum. Tú góðkennir tað, ella tú letur eina viðmerking eftir, og liðið vaknar og roynir aftur. Bara tú kanst flyta eitt kort til Liðugt.","Ein dagur við AI-gile, umleið. Um kvøldið letur tú nøkur viðmerkingar eftir: hesin knappurin er á skeivum stað, hin listin eigur at vera raðfest, kundi tað eisini fingið myrkan hátt. Tú fert í song. Agentarnir lesa viðmerkingarnar, gera broytingarnar, royna tær og geva tær aftur til tín. Um At gera tæmist, fyllir náttarvaktin tað úr backlog við kortum, sum ikki hava brúk fyri svari frá tær. Um morgunin er ein stuttur bunki: nøkur spurningar og nøkur ting at royna, hvørt við stigum, sum ein søvnugur maður kann fylgja, og skíggjamynd av, at tað riggar. Tú klikkar teg gjøgnum, góðkennir tey góðu og sendir restina aftur. Ein tokentalari vísir, hvat alt hetta brúkti, og Eingin token-hátturin er til tær magru vikurnar. So etur tú morgunmat, sum agentarnir ikki kunnu hjálpa við enn.","Fyrst, hvat AI-gile ikki er. Tað er ikki ein startup, tað er ikki til sølu, og ongin savnar tínar dátur. Tað er eitt ókeypis borð, sum koyrir á tíni teldu, uttan kontur, uttan fylgjarar og uttan cookies. Hvat tað er: ein rættilig støð at sæa allar AI-kodaverkætlanirnar í senn, við einum liði av agentum, sum gera kortini, og tær, sum taka avgerðirnar. Tað rennur kort saman, sum hanga saman, rættar ruglaðar heitir, og hevur eyga við, um kodan verður verandi lætt. Tað tosar umleið 120 mál, frá hollendskum og flamskum til sjóræningamál og klingonskt. Vinir kunnu senda hvønn øðrum boð, privat og krypterað. Tað varð bygt av Rich og nógvum tolnum agentum, mestsum við at brúka seg sjálvt. Tað er í lukkaðari pre-alfu, so tað er ruggað sums staðni. Um tað ljóðar stuttligt, bið vælsiðað, og kanska sleppur tú tíðliga inn."]}],"quips":{"1":"Eitt orð. Djarvt. Kanska ov djarvt.","3":"Trý orð. Longu ærligari enn flestu vøruvevir.","8":"Átta orð. Enn styttri enn ein standandi fundur.","21":"Longdirnar eru annars story points. Sjálvsagt eru tær tað.","55":"Fimmtiofimm orð. Tvey kort vórðu liðug, meðan tú las hetta.","144":"Hetta er tann langa. Ongin 233 er til. Agentarnir eru farnir í song."}},"timeline":{"first-idea.name":"Fyrsta hugskotið","first-idea.line":"Fyrsta samrøða av øllum, áðrenn nøkur koda var til.","first-board.name":"Fyrsta borð","first-board.line":"Eitt borð, sum fylgir sínum egna bygnaði: kort, súlur, drag og slepp, verkætlanir.","team-roles.name":"Lið og leiklutir","team-roles.line":"Agentprofilir, liðsmynstur, rúm og hvør ger hvat.","install.name":"Uppsetan og útgávur","install.line":"Ein zip, sum ein vinur kann seta upp, sjálvdagføring, rásir og afturrulling.","usage-saver.name":"Nýtslusparing","usage-saver.line":"Máta hvat koyringar kosta, halda kodu lættari, spara markið hjá tær.","friends.name":"Vinir og deiling","friends.line":"Privatar boð, ruglað relay, innbjóðingar, leiklutir og deild verkætlanir.","languages.name":"Mál","languages.line":"Hvør skíggjatekstur í einari málfílu, við hollendskum og flamskum fyrst.","ai-tester.name":"AI-royndari","ai-tester.line":"Ein royndari kannar hvørja yvirlatan fyrst og vísir, hvat hann sá.","website.name":"Heimasíðan","website.line":"aigile.lol, teaserin og henda tíðarlinjan.","streaming.name":"Prát og streymur","streaming.line":"Discord, Twitch, OBS, streymarahættur, GIF og emojir.","no-ai.name":"Útgáva uttan AI","no-ai.line":"Eitt borð til tey, sum koda uttan AI, og almenn borð.","night-watch.name":"Náttarvakt","night-watch.line":"Ein vaktari og ein Scrum Master halda liðunum við uppgávuna meðan tú sovir.","p-more.name":"Alt annað","p-more.line":"Smærri hugskot, sum bíða enn eftir síni tøk.","p-android.name":"Telefon og Android","p-android.line":"Kom til borðið hjá tær frá telefonini, síðani eitt upprunaligt Android-app.","p-release.name":"Alfa og longri","p-release.line":"Lukkað alfa, livandi heimasíðan, síðani beta.","p-languages.name":"Fleiri mál","p-languages.line":"Meiri enn hundrað mál, og ein niðurdýpingarháttur fyri tey, sum læra.","p-engines.name":"Fleiri AI-motorar","p-engines.line":"Vel Claude, Codex ella Gemini fyri hvønn agent.","p-pro.name":"Fakligur háttur","p-pro.line":"Vandamerki, samanrenningarbørur, hendingarkort og rekkverk.","p-self.name":"Varða um teg","p-self.line":"Móðurhættur, sjálvsrøktaráminningar og 4:20.","p-servers.name":"Ambætarar og vøkstur","p-servers.line":"Almennar ambætaraskipanir, leiklutir og ætlan fyri vøkstri.","p-livestream.name":"Streymiískoyti","p-livestream.line":"Twitch-prát, egnar emojir og eitt almennt beinleiðis sjónarhorn."},"words":{"button":"📖 Uppskipanarorð","h":"📖 Uppskipanarorð greinað","intro":"Orðini, sum uppskipanarfólk (og AI-toymini) brúka, á einføldum máli.","search":"Leita eftir einum orði…","none":"Einki orð samsvarar.","close":"Lat aftur","list":[{"id":"backlog","word":"Backlog","text":"Hugskot og arbeiði, sum ikki er ætlað enn. Einki verður gjørt við tað, fyrr enn tað fer til At gera."},{"id":"sprint","word":"Sprint","text":"Ein stuttur tíðarbolkur av arbeiði (ofta ein ella tvær vikur) við einum avtalaðum sett av kortum at gera liðug.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"Ein skjót innrokning: hvat hvør toymislimur gjørdi, hvat hann ger næst, og hvat steðgar honum.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Okkurt, sum ikki riggar, sum tað skal.","also":["bugs"]},{"id":"test","word":"Test","text":"At royna eitt liðugt stykki av arbeiði fyri at kanna, at tað ger tað, sum varð biðið um, áðrenn tú góðkennir tað.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Ein goymd mynd av koduni, við einum stuttum notati um, hvat broyttist. Tú kanst altíð fara aftur til eina.","also":["commits"]},{"id":"push","word":"Push","text":"At senda goymdar myndir (commits) frá hesi teldu upp á GitHub, so at tær eru trygdarviðgjørdar og deildar."},{"id":"branch","word":"Branch","text":"Ein sær lina av arbeiði í koduni, so at broytingar kunnu gerast uttan at nerta við høvuðsútgávuna.","also":["branches"]},{"id":"merge","word":"Merge","text":"At knýta broytingarnar hjá einum branch aftur inn í høvuðsútgávuna."},{"id":"repo","word":"Repo","text":"Mappan hjá verkætlanini við koduni og allari søguni av commits, vanliga eisini goymd á GitHub.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"At rudda koduna uttan at broyta, hvat hon ger: minni fílur, greiðari navn, minni endurtøka."},{"id":"deploy","word":"Deploy","text":"At seta eina nýggja útgávu í loftið, til dømis á ein ambætara, har fólk brúka hana."},{"id":"kanban","word":"Kanban","text":"Eitt borð við súlum (At gera, Í gerð, Liðugt), har kort flyta seg frá vinstru til høgru, sum arbeiðið gongur."},{"id":"wip","word":"WIP-mark","text":"Work in progress: flest kort, ein súla skal hava, so at toymið ger ting liðug, áðrenn tað byrjar fleiri.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"At biðja um, at broytingarnar hjá einum branch verða kannaðar og knýttar inn í høvuðsútgávuna.","also":["PR"]},{"id":"hook","word":"Hook","text":"Ein lítil skipan, sum koyrir av sær sjálvari á einum ásettum eyguablikki, t.d. tá ein AI-seta byrjar, so at toymið hoyrir tínar viðmerkingar.","also":["hooks"]},{"id":"token","word":"Token","text":"Eindin, sum AI-nýtsla verður tald í: umleið nøkur bókstavir av tekstið lisin ella skrivaður. Færri tokens, meira eftir av tíni ætlan.","also":["tokens"]},{"id":"agent","word":"Agent","text":"Ein AI, sum arbeiðir sjálvt við eini uppgávu: lesur koduna, ger broytingar, koyrir kanningar og boðar frá.","also":["agents"]}]}};
